module.exports = /*#__PURE__*/JSON.parse('{"id":"logica-programacion","pathId":"software-development","title":"Lógica de Programación","description":"Entrenamiento en resolución de problemas, abstracción y rigor mental. Una hoja de ruta de 16 temas (4 meses) diseñada para entender el \'porqué\' de cada bit antes de tocar una tecla.","level":"beginner","duration":"4 meses","isPublished":true,"publishedAt":"2024-02-17","updatedAt":"2024-02-17","topics":[{"id":"lp-m1-t1","title":"La Génesis del Dato y el Orden","order":1,"duration":"90 min","isPublished":true,"description":"Deconstruir la realidad mediante lógica pura, sin usar computadoras. Todo es papel, tablero y pensamiento estructurado."},{"id":"lp-m1-t2","title":"Abstracción de Sistemas Reales","order":2,"duration":"90 min","isPublished":true,"description":"Aprender a convertir procesos físicos en modelos lógicos. Introducción a Entidades y Estados."},{"id":"lp-m1-t3","title":"Lógica Proposicional y de Conjuntos","order":3,"duration":"90 min","isPublished":true,"description":"Comprender la base matemática de toda la programación. Tablas de verdad aplicadas a decisiones de ingeniería."},{"id":"lp-m1-t4","title":"El Flujo de la Verdad","order":4,"duration":"90 min","isPublished":true,"description":"Dominar los Diagramas de Flujo con rigor NASA. Cada camino debe estar validado; no se permiten flechas sueltas."},{"id":"lp-m2-t5","title":"Bifurcaciones Lógicas (Condicionales)","order":5,"duration":"90 min","isPublished":true,"description":"Dominar el arte del IF/ELSE. Aprender a crear protocolos de decisión donde cada milisegundo cuenta."},{"id":"lp-m2-t6","title":"La Tiranía de la Repetición (Bucles)","order":6,"duration":"90 min","isPublished":true,"description":"Comprender la diferencia técnica y etimológica entre FOR (conteo) y WHILE (estado). Entender el riesgo del bucle infinito."},{"id":"lp-m2-t7","title":"Optimización de Flujos","order":7,"duration":"90 min","isPublished":true,"description":"Aprender a reducir 10 pasos lógicos a 3 sin perder claridad. Introducción a la Complejidad Ciclomática."},{"id":"lp-m2-t8","title":"Evaluación de Medio Término (Reto Arquitectónico)","order":8,"duration":"180 min","isPublished":true,"description":"Diseñar la lógica completa de un sistema de soporte vital de una estación espacial en papel. Si hay una fuga lógica, el sistema falla."},{"id":"lp-m3-t9","title":"Anatomía de la Variable","order":9,"duration":"90 min","isPublished":true,"description":"Entender qué pasa físicamente en la memoria RAM cuando declaras un dato. Tipos de datos primitivos y su origen."},{"id":"lp-m3-t10","title":"Estructuras de Datos Lineales (Arreglos)","order":10,"duration":"90 min","isPublished":true,"description":"Comprender cómo organizar el caos en filas. Indexación y por qué empezamos a contar desde 0."},{"id":"lp-m3-t11","title":"Matrices y Multidimensionalidad","order":11,"duration":"90 min","isPublished":true,"description":"Aprender a pensar en 3D. Modelar datos complejos mediante matrices multidimensionales."},{"id":"lp-m3-t12","title":"Búsqueda y Ordenamiento Lógico","order":12,"duration":"90 min","isPublished":true,"description":"No es usar una función .sort(), es entender cómo se comparan los datos. Lógica de Burbuja vs. Búsqueda Binaria."},{"id":"lp-m4-t13","title":"La Caja Negra (Funciones y Procedimientos)","order":13,"duration":"90 min","isPublished":true,"description":"Dominar el principio de \'Divide y Vencerás\'. Cómo encapsular lógica para que sea reutilizable y robusta."},{"id":"lp-m4-t14","title":"Recursividad: El Espejo Infinito","order":14,"duration":"90 min","isPublished":true,"description":"Entender el concepto de una función que se llama a sí misma. El riesgo del desbordamiento de pila (Stack Overflow)."},{"id":"lp-m4-t15","title":"Documentación Forense y Algoritmia Avanzada","order":15,"duration":"90 min","isPublished":true,"description":"Aprender a escribir lógica que otros humanos puedan entender en 100 años. El código es para la máquina, la lógica es para los humanos."},{"id":"lp-m4-t16","title":"Defensa del Proyecto Final","order":16,"duration":"240 min","isPublished":true,"description":"Presentar un sistema complejo diagramado y pseudo-codificado. Debes defender cada decisión arquitectónica basándose en los principios vistos."}]}');

